<?php $pageTitle='Data Pasien'; require_once 'config/database.php'; require_once 'config/auth.php'; require_login();$q=trim($_GET['q']??'');$sql="SELECT * FROM patients";$params=[];if($q!==''){$sql.=" WHERE medical_record_no=? OR nik=? OR LOWER(name) LIKE LOWER(?)";$params=[$q,$q,'%'.$q.'%'];}$sql.=" ORDER BY id DESC LIMIT 40";$s=$pdo->prepare($sql);$s->execute($params);$rows=$s->fetchAll();$total=(int)$pdo->query("SELECT COUNT(*) FROM patients")->fetchColumn();include 'partials/header.php'; ?>
<div class="toolbar"><div><div class="eyebrow">DATABASE IDENTITAS</div><h2 style="margin:4px 0;color:#123a56;font-size:18px">Data pasien</h2><div class="muted"><?=$total?> pasien terdaftar dalam sistem</div></div><div class="actions"><a class="btn" href="<?=BASE_URL?>/registration_new.php">＋ Pasien Baru</a></div></div>
<div class="card"><form class="search" method="get"><input name="q" value="<?=e($q)?>" placeholder="Cari No. RM, NIK, atau nama pasien"><button class="btn">Cari Data</button><?php if($q!==''): ?><a class="btn secondary" href="<?=BASE_URL?>/patients.php">Reset</a><?php endif; ?></form></div>
<div class="card mt"><div class="card-title"><div><h2>Daftar pasien</h2><p>Gunakan data ini sebagai titik awal registrasi kunjungan berikutnya.</p></div></div><div class="table-wrap"><table><tr><th>Identitas</th><th>Tanggal Lahir</th><th>Kontak</th><th>Alamat</th><th>Status</th><th>Terdaftar</th></tr><?php foreach($rows as $p): ?><tr><td><b><?=e($p['name'])?></b><div class="muted"><?=e($p['medical_record_no'])?> • <?=e($p['nik'])?></div></td><td><?=e(date('d/m/Y',strtotime($p['dob'])))?><div class="muted"><?=($p['gender']==='L'?'Laki-laki':'Perempuan')?></div></td><td><?=e($p['phone']?:'—')?><div class="muted">Gol. darah <?=e($p['blood_type']?:'—')?></div></td><td><?=e($p['address']?:'—')?></td><td><span class="badge <?=((int)$p['duplicate_flag']?'red':'green')?>"><?=((int)$p['duplicate_flag']?'Validasi diperlukan':'Aktif')?></span></td><td><?=e(date('d/m/Y H:i',strtotime($p['created_at'])))?></td></tr><?php endforeach; ?></table><?php if(!$rows): ?><div class="empty">Tidak ada pasien yang sesuai dengan pencarian.</div><?php endif; ?></div></div>
